// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(bytes memory data) public {
        vm.assume(data.length <= 1024);

        bytes4 sel = bytes4(keccak256("version()"));
        bytes memory callData = abi.encodePacked(sel, data);

        (bool success, bytes memory ret) = address(c).call(callData);

        if (!success) {
            vm.assume(success);
        }

        if (ret.length < 64) {
            vm.assume(ret.length >= 64);
        }

        string memory s = abi.decode(ret, (string));
        bytes memory sb = bytes(s);

        vm.assume(sb.length > 0);

        assertTrue(sb[0] == bytes1(uint8(0x31)));
    }
}
